}

/**
 * Convert an OpenTelemetry span status code to an MLflow TraceState.
 * @param statusCode OpenTelemetry span status code
 * @returns The corresponding MLflow TraceState
 */
export function fromOtelStatus(statusCode: SpanStatusCode): TraceState {
  switch (statusCode) {
    case SpanStatusCode.OK:
      return TraceState.OK;
    case SpanStatusCode.ERROR:
      return TraceState.ERROR;
    case SpanStatusCode.UNSET:
    default:
      return TraceState.STATE_UNSPECIFIED;
  }
